      APE.ring(ctx, rx, ry, Rr, { subs: { 1: 'OH' }, color: t.ink, size: Math.max(13, Rr * 0.45) });
      Sim.label(ctx, 'phenol: o and p positions are electron-rich', rx, s.h - 26, { size: 12, weight: 650, color: t.ink2 });
